function(apptype,callback){
        console.log("Hisense_LoginWithVIDAA:" + apptype);
        var cmdInfo = {};
        cmdInfo.type = "APPMessage";
        cmdInfo.MsgType = "account";
        cmdInfo.action = "loginWithVidaa";
        cmdInfo.AppType = apptype;
        cmdInfo.fromFlag = "CSP";
        omi_platform.sendPlatformMessage(JSON.stringify(cmdInfo));

        handleLoginWithVIDAAEvent = function(event){
            var message = JSON.parse(event);
            if(message.type == "APPMessage" && message.MsgType == "LoginResult"){
                var GetResultInfo = message.AccoutInfo;
                callback(GetResultInfo);
            }
        }
        if(window.alreadyAddEventListener == 0){
            omi_platform.addPlatformEventListener(handleLoginWithVIDAAEvent);
            window.alreadyAddEventListener = 1;
        }
    }

