function(appinfo, callback) {
            if (!appinfo || typeof (appinfo) != 'object') {
                callback({ret: false, msg:{appId: '', message:'wrong param'}})
                return false
            }
            if(!appinfo?.packageName) {
                const ret = Hisense_installApp(appinfo.appId, appinfo.appName, appinfo.thumbnail, appinfo.iconSmall, appinfo.iconBig, appinfo.appUrl, appinfo.storetype, callback, appinfo.configUrl, appinfo.configUrlDownload, appinfo.mediaId)
                callback({ret: ret, msg:{appId: appinfo?.appId, message: ret? "succeed" : "install failed!"}})
                return ret
            } else {
                // package app
                const param = {
                     pkgName: appinfo?.packageName,
                     version: '',
                     appId: appinfo?.appId
                }
                this.sendPkgmgrRequest('install', param, appinfo, callback)
                return true
            }
        }

function(api, args, appinfo, callback) {
            let ret = true
            // encode param
            const encodedData = encodeURIComponent(JSON.stringify(args));
            const url = `https://localhost:9888/service/pkgmgr?api=${api}&args=${encodedData}`;
            const xhr = new XMLHttpRequest();
            xhr.onload = function() {
                if (xhr.status >= 200 && xhr.status < 300) {
                    // 请求成功，处理响应数据
                    console.log(xhr.responseText)
                    const response = JSON.parse(xhr.responseText)
                    if(response?.ret && api == 'install') {
                        // TODO: read from config file
                        const path = `file:///APPS/pkgs/${args?.pkgName}/index.html`
                        // write path into Appinfo.json
                        ret = Hisense_installApp(args?.appId, args?.pkgName, appinfo?.thumbnail, appinfo?.iconSmall, appinfo?.iconBig, path, 'hisense', callback, appinfo?.configUrl, appinfo?.configUrlDownload, appinfo?.mediaId)
                    }

                    callback({ret: response?.ret, msg:{appId: args?.appId, message: response?.msg}})
                } else {
                    // 请求失败，处理错误
                    ret = false
                    callback({ret: ret, msg:{appId: args?.appId, message: xhr.responseText}})
                }
            }

            xhr.open('GET', url);
            xhr.send();
            return ret
        }
